class Solution:
    def setZeroes(self, matrix):
        if not matrix or not matrix[0]:
            return

        rows = len(matrix)
        cols = len(matrix[0])
        zero_rows = set()
        zero_columns = set()

        for row in range(rows):
            for col in range(cols):
                if matrix[row][col] == 0:
                    zero_rows.add(row)
                    zero_columns.add(col)

        for row in range(rows):
            for col in range(cols):
                if row in zero_rows or col in zero_columns:
                    matrix[row][col] = 0
